// Census time series for the Core Report explorer: every downtown core and its
// region in each census year sdsc-data has pulled (2001 and 2021 today).
//
// coreSeries.csv is generated by `npm run core-series`, which trims sdsc-data's
// downtown_vs_cma_comparison.csv to the downtowns profiled here. Without the
// file the "change" module stays hidden. It loads as its own chunk so it never
// weighs down the rest of the page.

import { csvParse } from 'd3';
import { CITIES } from '../lib/data/coredata/coreData.js';

// Imported as raw text and parsed here: a third the size of the row objects
// the CSV plugin would otherwise inline into the chunk.
const sources = import.meta.glob('../lib/data/coredata/coreSeries.csv', {
	query: '?raw',
	import: 'default'
});
const loadCsv = Object.values(sources)[0];

/** True when coreSeries.csv is present in the build. */
export const SERIES_AVAILABLE = Boolean(loadCsv);

const THEME_LABELS = {
	overall_growth: 'Growth',
	migration_and_imm: 'Migration',
	housing_supply: 'Housing',
	Demographics: 'People & work'
};

const CITY_NAME = Object.fromEntries(CITIES.map((c) => [c.key, c.name]));

function num(raw) {
	if (raw == null || raw === '' || raw === 'NA') return null;
	const value = Number(raw);
	return Number.isFinite(value) ? value : null;
}

const slug = (text) =>
	String(text ?? '')
		.toLowerCase()
		.replace(/[^a-z0-9]+/g, '-')
		.replace(/^-|-$/g, '');

/**
 * Reshapes coreSeries rows into themes → indicators → variables. Each variable
 * carries one entry per downtown in the shape the beeswarm reads:
 * `{ key, name, downtown: { [year]: value }, cma: { [year]: value } }`.
 *
 * Shares (percent of the indicator's total) are plotted wherever the pipeline
 * computed one, because they compare fairly as populations grow; variables
 * without a share (population, dwellings) fall back to the raw value. "Total …"
 * rows are denominators and are left out.
 */
export function buildSeries(rows) {
	const years = (rows.columns ?? Object.keys(rows[0] ?? {}))
		.map((column) => Number(column.match(/^value_(\d{4})_dt$/)?.[1]))
		.filter(Boolean)
		.sort((a, b) => a - b);

	const themes = new Map();
	for (const row of rows) {
		if (!row.variable_name || /^total\b/i.test(row.variable_name)) continue;

		if (!themes.has(row.theme)) {
			themes.set(row.theme, {
				key: slug(row.theme),
				label: THEME_LABELS[row.theme] ?? row.theme,
				indicators: new Map()
			});
		}
		const indicators = themes.get(row.theme).indicators;
		if (!indicators.has(row.indicator)) {
			indicators.set(row.indicator, {
				key: `${slug(row.theme)}--${slug(row.indicator)}`,
				label: row.indicator,
				variables: new Map()
			});
		}
		const variables = indicators.get(row.indicator).variables;
		if (!variables.has(row.variable_name)) variables.set(row.variable_name, []);
		variables.get(row.variable_name).push(row);
	}

	return {
		years,
		themes: [...themes.values()].map((theme) => ({
			key: theme.key,
			label: theme.label,
			indicators: [...theme.indicators.values()].map((indicator) => ({
				key: indicator.key,
				label: indicator.label,
				variables: [...indicator.variables].map(([name, list]) =>
					finishVariable(indicator, name, list, years)
				)
			}))
		}))
	};
}

function finishVariable(indicator, name, rows, years) {
	const hasShare = rows.some((r) => years.some((yr) => num(r[`percent_${yr}_dt`]) != null));
	const field = hasShare ? 'percent' : 'value';
	const isIncome = /average/i.test(name) && /income/i.test(name);

	const cities = rows.map((row) => {
		const read = (geo) =>
			Object.fromEntries(years.map((yr) => [yr, num(row[`${field}_${yr}_${geo}`])]));
		return {
			key: row.city,
			name: CITY_NAME[row.city] ?? row.city,
			downtown: read('dt'),
			cma: read('cma')
		};
	});

	// "Household Size: 1 person" reads as "1 person" under its indicator.
	const prefix = `${indicator.label}: `;
	const label = name.startsWith(prefix) ? name.slice(prefix.length) : name;

	return {
		key: `${indicator.key}--${slug(name)}`,
		label,
		title: name,
		indicator: indicator.label,
		cities,
		// Census years in which at least one downtown has a value; a variable can
		// only be animated between two of these.
		years: years.filter((yr) => cities.some((c) => c.downtown[yr] != null)),
		format: hasShare ? 'pct' : isIncome ? 'money' : 'int',
		// Raw counts run from a few thousand downtown residents to millions in a
		// region, so they need a log axis to stay readable; shares and incomes don't.
		scale: hasShare || isIncome ? 'lin' : 'log',
		zeroFloor: hasShare,
		nominalDollars: isIncome
	};
}

/** Loads and reshapes coreSeries.csv, or resolves empty when it isn't present. */
export async function loadSeries() {
	if (!loadCsv) return { years: [], themes: [] };
	return buildSeries(csvParse(await loadCsv()));
}
